export default function JohnTheBaptist({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        {/* Stable white paper underneath every paint region. */}
        <rect
          x="0"
          y="0"
          width="1024"
          height="1536"
          fill={PAPER}
          pointerEvents="none"
        />

        {/* Open sky / background inside the arched composition. */}
        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1024" height="1536" />
        </g>

        {/* Cloud banks framing St. John. */}
        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} />
        </g>

        {/* Circular halo behind the head. */}
        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} />
        </g>

        {/* Outer cloak / draped mantle and sleeves. */}
        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} />
        </g>

        {/* Camel-hair garment / fur tunic and lower inner clothing. */}
        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} />
        </g>

        {/* Face, neck, and both visible hands. */}
        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} />
        </g>

        {/* Hair, moustache, and beard. */}
        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} />
        </g>

        {/* Reed cross, Ecce Agnus Dei banner, and rope / cord details. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} />
        </g>

        {/* Lamb of God. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} />
        </g>

        {/* Exact traced black line art from the supplied John the Baptist image.
            Keep this last and non-interactive so every region remains paintable. */}
        <path
          {...detail}
          {...ink}
          d={JOHN_THE_BAPTIST_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}